"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["26047"],{59547(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.formulario_portavel.derivacao_invalida","status":422,"titulo":"A deriva\xe7\xe3o do formul\xe1rio n\xe3o forma regras v\xe1lidas"},"descricao":{"codigo":"uniplus.formulario_portavel.derivacao_invalida","requisitos":[],"oQueAconteceu":["A avalia\xe7\xe3o de um formul\xe1rio sem cadastro confere as regras de um formul\xe1rio apresentado contra respostas simuladas, sem gravar nada nem registrar o conte\xfado enviado. Uma deriva\xe7\xe3o de fato nas regras recebidas \xe9 recusada por um destes motivos, cada um com a pr\xf3pria mensagem: uma regra sem `quando`, como \\"Uma regra de \'`{fato\\\\}`\' n\xe3o diz quando ativa; a regra sempre ativa tem a lista vazia.\\"; uma deriva\xe7\xe3o sem nenhuma regra, como \\"A deriva\xe7\xe3o de \'`{fato\\\\}`\' precisa de ao menos uma regra.\\"; ou uma regra que cita o pr\xf3prio fato derivado, como \\"A deriva\xe7\xe3o de \'`{fato\\\\}`\' cita o pr\xf3prio fato \u2014 um derivado n\xe3o pode depender de si mesmo.\\"","A recusa vem no corpo da resposta, com o c\xf3digo e o `detail` que traz a mensagem, sem lista `errors`. As regras recebidas s\xe3o lidas por inteiro antes da avalia\xe7\xe3o, e a leitura para na primeira recusa, nesta ordem: o elemento nulo, as p\xe1ginas (com os itens e os grupos de cada uma), os termos, as deriva\xe7\xf5es, os resumos de grupo e, por fim, o conjunto. A regra de deriva\xe7\xe3o categ\xf3rica sem o c\xf3digo que contribui \xe9 recusada com outro c\xf3digo.","As propriedades de texto que o corpo n\xe3o pode omitir, como o c\xf3digo, a obrigatoriedade e a opera\xe7\xe3o, ausentes ou nulas, s\xe3o recusadas antes, com 400 e sem c\xf3digo deste cat\xe1logo, pela leitura do corpo."],"comoResolver":["Informe `quando` em toda regra, usando a lista vazia para a regra sempre ativa; mantenha ao menos uma regra em cada deriva\xe7\xe3o; e tire de cada regra a cita\xe7\xe3o ao pr\xf3prio fato derivado. Depois, repita a avalia\xe7\xe3o."],"ondeAparece":["Avalia\xe7\xe3o de formul\xe1rio sem cadastro"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Formulario portavel"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);